<?php
declare(strict_types=1); require_once __DIR__.'/../_helper.php'; pengaturan_kehadiran_admin_only();
$tp=$pdo->query("SELECT id,nama FROM tahun_pelajaran WHERE aktif=1 ORDER BY id DESC LIMIT 1")->fetch(); if(!$tp) exit('Belum ada tahun pelajaran aktif.');
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_valid_csrf();$aksi=(string)($_POST['aksi']??'');
 if($aksi==='simpan'){$tanggal=(string)($_POST['tanggal']??'');$jenis=(string)($_POST['jenis']??'');$nama=trim((string)($_POST['nama']??''));$ket=trim((string)($_POST['keterangan']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$tanggal))$errors[]='Tanggal tidak valid.';if(!in_array($jenis,['libur','masuk_khusus'],true))$errors[]='Jenis kalender tidak valid.';if($nama==='')$errors[]='Nama kegiatan wajib diisi.';if(!$errors){$st=$pdo->prepare('INSERT INTO kalender_kehadiran (tahun_pelajaran_id,tanggal,jenis,nama,keterangan,created_by) VALUES (?,?,?,?,?,?) ON DUPLICATE KEY UPDATE jenis=VALUES(jenis),nama=VALUES(nama),keterangan=VALUES(keterangan),created_by=VALUES(created_by)');$st->execute([$tp['id'],$tanggal,$jenis,$nama,$ket?:null,user_id()]);pengaturan_kehadiran_audit($pdo,'SAVE_KALENDER_KEHADIRAN',null,'Kalender '.$tanggal.' '.$jenis.' '.$nama);$ok='Pengecualian kalender berhasil disimpan.';}}
 if($aksi==='hapus'){$id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT tanggal,nama FROM kalender_kehadiran WHERE id=? AND tahun_pelajaran_id=?');$st->execute([$id,$tp['id']]);$r=$st->fetch();if($r){$pdo->prepare('DELETE FROM kalender_kehadiran WHERE id=?')->execute([$id]);pengaturan_kehadiran_audit($pdo,'DELETE_KALENDER_KEHADIRAN',$id,'Menghapus pengecualian '.$r['tanggal'].' '.$r['nama']);$ok='Pengecualian dihapus.';}}
}
$st=$pdo->prepare('SELECT * FROM kalender_kehadiran WHERE tahun_pelajaran_id=? ORDER BY tanggal');$st->execute([$tp['id']]);$rows=$st->fetchAll();
$page_title='Kalender Kehadiran';require_once __DIR__.'/../../layouts/header.php';require_once __DIR__.'/../../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Pengaturan Absensi</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1>Kalender Kehadiran</h1><p>Atur pengecualian dari pola hari sekolah otomatis · Tahun <?=e($tp['nama'])?>.</p></div><div class="page-header-actions"><a class="btn btn-secondary" href="<?=BASE_URL?>pengaturan_absensi/jadwal/index.php"><i class="bi bi-calendar3"></i> Jadwal Kehadiran</a><a class="btn btn-secondary" href="<?=BASE_URL?>absensi/index.php"><i class="bi bi-calendar-check"></i> Absensi Kehadiran</a></div></div><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><?php if(!empty($ok)):?><div class="alert alert-success"><?=e($ok)?></div><?php endif;?><div class="form-card"><form method="post"><?=csrf_field()?><input type="hidden" name="aksi" value="simpan"><div class="form-grid"><label>Tanggal *<input class="form-control" type="date" name="tanggal" required></label><label>Jenis *<select class="form-control" name="jenis" required><option value="libur">Libur</option><option value="masuk_khusus">Masuk Khusus</option></select></label><label>Nama *<input class="form-control" name="nama" maxlength="150" required placeholder="Contoh: Libur Hari Besar"></label><label>Keterangan<input class="form-control" name="keterangan" maxlength="255" placeholder="Opsional"></label></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-check2-circle"></i> Simpan Pengecualian</button></div></form></div><div class="dashboard-table-card" style="margin-top:20px"><div class="section-title"><div><h2>Pengecualian Kalender</h2><p>Jika tanggal tidak ada di sini, sistem mengikuti jadwal hari mingguan.</p></div></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Nama</th><th>Keterangan</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="empty-state">Belum ada pengecualian kalender.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><span class="status-badge status-<?=e($r['jenis']==='libur'?'nonaktif':'aktif')?>"><?=e($r['jenis']==='libur'?'Libur':'Masuk Khusus')?></span></td><td><strong><?=e($r['nama'])?></strong></td><td><?=e((string)($r['keterangan']??'-'))?></td><td><form method="post" style="display:inline" onsubmit="return confirm('Hapus pengecualian ini?')"><?=csrf_field()?><input type="hidden" name="aksi" value="hapus"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-secondary btn-sm btn-icon-sm" title="Hapus" aria-label="Hapus"><i class="bi bi-trash3" aria-hidden="true"></i></button></form></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><?php require_once __DIR__.'/../../layouts/footer.php';?>
